#include <cstdio>
#include <algorithm>
using namespace std;

int cycle(long long n) {
    int length = 1;
    while (n != 1) {
        n = (n % 2) ? 3 * n + 1 : n / 2;
        length++;
    }
    return length;
}

int main() {
    int i, j;
    while (scanf("%d %d", &i, &j) == 2) {
        int low = min(i, j), high = max(i, j), best = 0;
        for (int n = low; n <= high; n++) best = max(best, cycle(n));
        printf("%d %d %d\n", i, j, best);
    }
}

